fn setup(){
 assert!(!r("build-plan.json").exists());
 let full=read(format!("{C}/analysis.json"));assert_eq!(full["gate_passed"],false);assert_eq!(full["failed_checks"],json!(["1x2-w16/OFF/accepted"]));
 let mut pins:BTreeMap<String,String>=serde_json::from_value(read(format!("{C}/pins.json"))).unwrap();for(p,h)in &pins{assert_eq!(hash(p),*h);}
 fn copy_source(from:&Path,to:&Path,pins:&mut BTreeMap<String,String>,count:&mut usize){fs::create_dir_all(to).unwrap();for e in fs::read_dir(from).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){copy_source(&e.path(),&to.join(e.file_name()),pins,count);}else{let p=to.join(e.file_name());fs::copy(e.path(),&p).unwrap();assert_eq!(hash(&p),hash(e.path()));pin(pins,e.path());pin(pins,p);*count+=1;}}}
 let mut count=0;copy_source(&Path::new(P).join("source"),&r("source"),&mut pins,&mut count);assert_eq!(count,175);
 fs::copy(format!("{P}/source-audit.json"),r("source-audit.json")).unwrap();
 // Inherit field tests only when every actual field source/manifests match.
 let mut old_fields=Vec::new();fn field_files(p:&Path,out:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let e=e.unwrap();if e.file_type().unwrap().is_dir(){field_files(&e.path(),out);}else{out.push(e.path());}}}
 let old=Path::new("/home/ubuntu/src/zopro-perf-work/g2-borrowed-qualification/source/crates/zopro-bn254");field_files(old,&mut old_fields);assert!(old_fields.len()>10);for f in &old_fields{let rel=f.strip_prefix(old).unwrap();let current=r("source/crates/zopro-bn254").join(rel);assert_eq!(hash(&current),hash(f));pin(&mut pins,f);}
 let old_tests="/home/ubuntu/src/zopro-perf-work/g2-borrowed-qualification/build/portable-field/tests.json";let fields=read(old_tests);assert_eq!(fields["passed_tests"].as_array().unwrap().len(),11);pin(&mut pins,old_tests);
 save(r("inherited-field-tests.json"),&json!({"portable_field_tests":11,"field_source_files_checked":old_fields.len(),"receipt":old_tests,"new_field_tests":0,"same_arithmetic_source":true}));
 let mut env=read(format!("{C}/run-plan.json"))["steps"][0]["environment"].clone();let flags=fs::read_to_string(format!("{P}/native-flags.txt")).unwrap().replace("target-cpu=native","target-cpu=x86-64");env["RUSTFLAGS"]=json!(format!("{flags} --cfg zopro_balanced_kh --cfg no_ifma --cfg no_asm"));env["CARGO_TARGET_DIR"]=json!(r("target-portable"));env["CARGO_BUILD_JOBS"]=json!("16");env["RAYON_NUM_THREADS"]=json!("4");save(r("portable-environment.json"),&env);
 let cargo=r("source/Cargo.toml");let mut steps=Vec::new();
 steps.push(json!({"kind":"command","name":"portable-core","argv":["cargo","test","--manifest-path",cargo,"--locked","--offline","--release","-p","zopro-core","--lib","--","--test-threads=1","--nocapture"],"environment":env,"unfiltered":true,"required_tests":["msm_affine::borrowed_pending::balanced::tests::variable_booth_digits_reconstruct_exact_integers","msm_affine::borrowed_pending::balanced::tests::balanced_complete_generator_oracle_and_uniform_control"],"timeout_seconds":1800}));
 steps.push(json!({"kind":"command","name":"portable-prover","argv":["cargo","test","--manifest-path",cargo,"--locked","--offline","--release","-p","zopro-prover","--lib","--test","cubic","--","--test-threads=1"],"environment":env,"unfiltered":true,"timeout_seconds":1800}));
 steps.push(json!({"kind":"command","name":"portable-libraries","argv":["cargo","build","--manifest-path",cargo,"--locked","--offline","--release","-p","zopro-bench","--lib","--message-format=json"],"environment":env,"timeout_seconds":1800}));
 steps.push(json!({"kind":"command","name":"freeze-portable","argv":[r("prepare"),"freeze"],"environment":env,"timeout_seconds":180}));
 steps.push(json!({"kind":"link-sdk","name":"portable","artifacts":r("portable-cargo.jsonl"),"driver":format!("{Z}/crates/zopro-bench/examples/cpu-sdk.rs"),"additional_sources":[format!("{Z}/crates/zopro-bench/examples/support/perf.rs")],"rustc_flags":["-O","-C","target-cpu=x86-64","-C","lto=fat","-C","codegen-units=1"],"timeout_seconds":600}));
 for v in ["accepted","on"]{let label=if v=="accepted"{"control"}else{"candidate"};let artifacts=format!("{P}/frozen-{label}-cargo.jsonl");pin(&mut pins,&artifacts);for(driver,source)in[("warm","warm.rs"),("concurrent","concurrent.rs")]{steps.push(json!({"kind":"link-sdk","name":format!("{v}-{driver}"),"artifacts":artifacts,"driver":r(source),"timeout_seconds":600}));}}
 assert_eq!(steps.len(),9);
 let peak=full["cells"]["1x2-w32/accepted"]["max_RSS_MiB"].as_f64().unwrap();let max=((peak*1.25/64.).ceil()*64.)as u64;let high=((peak*0.9/8.).ceil()*8.)as u64;assert_eq!(max,192);assert_eq!(high,128);save(r("resource-limit-derivation.json"),&json!({"baseline_peak_RSS_MiB":peak,"test_memory_max_MiB":max,"test_warm_high_MiB":high,"warm_priming_max_MiB":512,"ballast_MiB":32,"swap_max":0,"not_a_product_memory_cap":true,"not_minimum_RAM":true}));
 save(r("source-reuse.json"),&json!({"source_files":175,"originals_exact":173,"reverse174_exact":true,"source_byte_exact_to_pilot":P,"native_tests_reused":true,"native_core_tests":{"OFF":122,"ON":124},"native_prover_tests_each":8,"new_native_tests":0,"full_performance_gate_passed":false,"performance_report":format!("{Z}/docs/benchmarks/2026-10-28-balanced-kh-qualification175/README.md"),"production_changed":false}));
 for f in ["prepare.rs","prepare","setup.rs","adapt.rs","design.md","warm.rs","concurrent.rs","portable-environment.json","source-audit.json","source-reuse.json","inherited-field-tests.json","resource-limit-derivation.json"]{pin(&mut pins,r(f));}for f in ["analysis.json","proof-inventory.json","calibration-audit.json"]{pin(&mut pins,format!("{C}/{f}"));}
 let history=format!("{Z}/docs/benchmarks/2026-10-26-control-rescheduling/README.md");pin(&mut pins,&history);
 save(r("build-pins.json"),&json!(pins));save(r("build-plan.json"),&json!({"version":1,"source_pins":r("build-pins.json"),"steps":steps}));println!("Prepared9portable/native-consumer buildsteps;exact175source;field11/native122124+8tests inherited;fullperformancegate stillfalse");
}
